func newApprovalRunItem() unsafe.Pointer {
	return unsafe.Pointer(new(billingapprovalrun.ApprovalRunItem))
}

func newNApprovalRunItem(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]billingapprovalrun.ApprovalRunItem, n)))
}

func ptrApprovalRunItem(p unsafe.Pointer, c int32) any {
	r := (*billingapprovalrun.ApprovalRunItem)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RunID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ItemID))
	case 5:
		return (*int64)(unsafe.Pointer(&r.Sequence))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return (*string)(unsafe.Pointer(&r.FailureCode))
	case 8:
		return &r.ErrorMessage
	case 9:
		return (**string)(unsafe.Pointer(&r.InvoiceID))
	case 10:
		return &r.InvoiceNumber
	case 11:
		return &r.ProcessedAt
	case 12:
		return &r.CreatedAt
	case 13:
		return &r.UpdatedAt
	}
	return nil
}

func valueApprovalRunItem(p unsafe.Pointer, c int32) any {
	r := (*billingapprovalrun.ApprovalRunItem)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RunID)
	case 4:
		return string(r.ItemID)
	case 5:
		return int64(r.Sequence)
	case 6:
		return string(r.Status)
	case 7:
		if r.FailureCode == "" {
			return nil
		}
		return string(r.FailureCode)
	case 8:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 9:
		if r.InvoiceID == nil {
			return nil
		}
		return string(*r.InvoiceID)
	case 10:
		if r.InvoiceNumber == "" {
			return nil
		}
		return r.InvoiceNumber
	case 11:
		if r.ProcessedAt == nil {
			return nil
		}
		return *r.ProcessedAt
	case 12:
		return r.CreatedAt
	case 13:
		return r.UpdatedAt
	}
	return nil
}

func init() {
	approvalRunsTable.Relations[0].Target = ApprovalRunItemsSchema()
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

var enumApprovalFailureCode = [...]schema.EnumValue{
	{Value: `NotReady`, Label: `Approval Failure Not Ready`},
	{Value: `AlreadyDone`, Label: `Approval Failure Already Done`},
	{Value: `OnHold`, Label: `Approval Failure On Hold`},
	{Value: `Undone`, Label: `Approval Failure Undone`},
	{Value: `Unexpected`, Label: `Approval Failure Unexpected`},
	{Value: `NotApplicable`, Label: `Approval Failure Not Applies`},
}

var enumApprovalItemStatus = [...]schema.EnumValue{
	{Value: `Pending`, Label: `Approval Item Pending`},
	{Value: `Succeeded`, Label: `Approval Item Succeeded`},
	{Value: `Failed`, Label: `Approval Item Failed`},
	{Value: `Skipped`, Label: `Approval Item Skipped`},
}

var enumApprovalRunStatus = [...]schema.EnumValue{
	{Value: `Scheduled`, Label: `Approval Run Scheduled`, Doc: `ApprovalRunScheduled is inside the undo window; nothing is approved yet.`},
	{Value: `Running`, Label: `Approval Run Running`},
	{Value: `Completed`, Label: `Approval Run Completed`},
	{Value: `Undone`, Label: `Approval Run Undone`, Doc: `ApprovalRunUndone was taken back inside the window and wrote nothing.`},
	{Value: `Failed`, Label: `Approval Run Failed`},
}

var enumRunAction = [...]schema.EnumValue{
	{Value: `Approve`, Label: `Approve`},
	{Value: `Post`, Label: `Post`},
	{Value: `Hold`, Label: `Hold`},
	{Value: `Assign`, Label: `Assign`},
	{Value: `Cancel`, Label: `Cancel`},
	{Value: `RequestPaperwork`, Label: `Request Paperwork`},
	{Value: `ResolveIssue`, Label: `Resolve Issue`},
}

